// PNG files of 16 bits per channel. SDL_image reads PNG with its own stb_image, which cuts such files down to 8 bits while loading, so
// they are read here with the whole 16 bits, for textures that can keep more than 8 of them.

#include <cstring>

#include <SDL3/SDL.h>

#include "graphics_internal.hpp"

#define STB_IMAGE_STATIC
#define STB_IMAGE_IMPLEMENTATION
#define STBI_ONLY_PNG
#define STBI_NO_STDIO
#define STBI_NO_LINEAR
#define STBI_NO_HDR
#define STBI_NO_THREAD_LOCALS
#include "stb_image.h"

namespace bb::gfx {

	bool png_has_16_bits(const uint8_t* data, size_t size)
	{
		// The signature, then the IHDR chunk: length, type, width, height, bit depth, color type.
		if ((size < 26) || memcmp(data, "\x89PNG\r\n\x1a\n", 8) || memcmp(data + 12, "IHDR", 4)) {
			return false;
		}
		return (data[24] == 16) && (data[25] != 3);
	}

	SDL_Surface* load_png_16(const uint8_t* data, size_t size, bool& has_alpha)
	{
		int       w = 0, h = 0, channels = 0;
		stbi_us*  pixels = stbi_load_16_from_memory(data, int(size), &w, &h, &channels, 4);
		if (!pixels) {
			return nullptr;
		}
		SDL_Surface* surface = SDL_CreateSurface(w, h, SDL_PIXELFORMAT_RGBA64);
		if (surface) {
			for (int y = 0; y < h; y++) {
				memcpy(static_cast<uint8_t*>(surface->pixels) + size_t(y) * size_t(surface->pitch), pixels + size_t(y) * size_t(w) * 4, size_t(w) * 8);
			}
		}
		stbi_image_free(pixels);
		has_alpha = (data[25] == 4) || (data[25] == 6);
		return surface;
	}

} // namespace bb::gfx
